INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Combined Oral Contraceptives','easy','flashcard','What hormones are contained in the combined oral contraceptive pill (COCP)?','["Synthetic oestrogen (ethinylestradiol) + synthetic progestogen (e.g., levonorgestrel, desogestrel, norethisterone, or drospirenone)"]','A','The COCP combines two synthetic hormones. The oestrogen component is almost always ethinylestradiol. The progestogen varies between formulations and generations, affecting androgenicity and side-effect profile.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Combined Oral Contraceptives','easy','flashcard','What is the primary mechanism of contraception of the COCP?','["Suppression of the midcycle LH surge, preventing ovulation. Secondary mechanisms: thickening of cervical mucus (impeding sperm) and endometrial atrophy (reducing implantation chances)."]','A','The dominant mechanism is inhibition of ovulation. The COCP suppresses GnRH pulse frequency by providing continuous oestrogen and progestogen feedback, preventing the LH surge required for follicular rupture.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Combined Oral Contraceptives','medium','flashcard','Name four absolute contraindications (UKMEC 4) to the combined oral contraceptive pill.','["1. Personal history of VTE or known thrombophilia (e.g., Factor V Leiden). 2. Migraine with aura. 3. Smoking >15 cigarettes/day AND age >35. 4. Personal history of breast cancer (current or recent). Also: ischaemic heart disease, stroke, uncontrolled hypertension, breastfeeding <6 weeks postpartum."]','A','These represent conditions where the risks of oestrogen outweigh the benefits. The UKMEC 4 category means the method should not be used. Migraine with aura carries a 2-fold increased stroke risk that is amplified further by oestrogen.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Combined Oral Contraceptives','medium','flashcard','Why does rifampicin reduce the efficacy of the COCP?','["Rifampicin is a potent CYP3A4 enzyme inducer. It accelerates hepatic metabolism of ethinylestradiol and progestogen, reducing plasma drug levels below the contraceptive threshold. Additional contraception (e.g., barrier method) is required during rifampicin treatment and for 28 days after."]','A','This is the most clinically important drug interaction with the COCP. Other enzyme inducers include carbamazepine, phenytoin, phenobarbital, primidone, topiramate, and St John''s Wort. The interaction does not occur with isoniazid or ethambutol.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Combined Oral Contraceptives','easy','flashcard','List three non-contraceptive benefits of the COCP.','["1. Reduced risk of ovarian cancer (50% reduction with long-term use). 2. Reduced risk of endometrial cancer. 3. Improvement in dysmenorrhoea and menorrhagia. Also: reduced acne (particularly with anti-androgenic progestogens), reduced PMS symptoms, and protective against pelvic inflammatory disease (cervical mucus barrier)."]','A','The non-contraceptive benefits of the COCP are clinically important and should be discussed when counselling patients. Protection against ovarian and endometrial cancer persists for years after stopping.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Combined Oral Contraceptives','medium','flashcard','How does oestrogen in the COCP increase VTE risk?','["Oestrogen undergoes first-pass hepatic metabolism, upregulating synthesis of pro-coagulant factors (VII, VIII, X, fibrinogen) and reducing natural anticoagulants (protein C, protein S, antithrombin). This creates a pro-thrombotic state, approximately doubling baseline VTE risk."]','A','The prothrombotic effect is why oestrogen-containing contraceptives are contraindicated in women with thrombophilia (e.g., Factor V Leiden) or prior VTE. Transdermal delivery avoids first-pass hepatic effects, explaining why transdermal HRT has lower VTE risk than oral.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Combined Oral Contraceptives','hard','flashcard','Compare the androgenic activity of first- and third-generation COCP progestogens.','["First/second-generation progestogens (norethisterone, levonorgestrel) have significant androgenic activity, potentially causing acne, hirsutism, and unfavourable lipid profiles (reduced HDL). Third-generation progestogens (desogestrel, gestodene) and fourth-generation (drospirenone) have much lower androgenicity; drospirenone has anti-androgenic activity and is used in acne/PCOS. Third-generation progestogens have slightly higher VTE risk than second-generation."]','A','The choice of progestogen affects both the androgenic side-effect profile and VTE risk. Third-generation progestogens are better for women with androgen-sensitive skin conditions but carry marginally higher VTE risk.','universal',false,'{year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Combined Oral Contraceptives','easy','flashcard','What is the 7-day rule for missed combined oral contraceptive pills?','["If 1 pill is missed (<48 hours late): take the missed pill immediately, continue as normal, no extra precautions. If 2+ pills are missed (>48 hours late): take the most recently missed pill, use condoms for 7 days, and if missed pills were in week 1 and unprotected sex occurred, consider emergency contraception. If missed in week 3, run two packs together without a pill-free interval."]','A','The 7-day rule reflects the time required to re-establish suppression of the hypothalamic-pituitary-ovarian axis after missed pills. The pill-free interval is the period of greatest risk of ovulation if pills are missed.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Combined Oral Contraceptives','hard','flashcard','What is the relationship between the COCP and cervical cancer risk?','["The COCP is associated with a small increased risk of cervical cancer with long-term use (relative risk ~1.6 after 5+ years). The risk returns to baseline within 10 years of stopping. The mechanism is not direct carcinogenesis; rather, COCP users may have more sexual partners or be less likely to use barrier methods, increasing HPV exposure, and oestrogen/progestogen may promote HPV integration or progression of CIN."]','A','The cervical cancer association is confounded by sexual behaviour. HPV vaccination and regular cervical screening are the primary preventive strategies. The COCP is not absolutely contraindicated in cervical cancer risk, but CIN 3 or invasive cancer is a contraindication.','universal',false,'{year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Combined Oral Contraceptives','medium','flashcard','What is the mechanism of the pill-free interval in the 21-day COCP regimen?','["During the 7-day pill-free interval, the withdrawal of exogenous oestrogen and progestogen causes endometrial shedding (withdrawal bleed). This bleed is not a true menstrual period — it is not a sign of ovulation. The hypothalamic-pituitary-ovarian axis begins to recover during this interval, which is why pill-free intervals >7 days risk ovulation and contraceptive failure."]','A','The pill-free interval (or placebo week in 28-day packs) was included to produce a withdrawal bleed thought to reassure users they were not pregnant. It is not physiologically necessary for contraception. Extended and continuous regimens (no pill-free intervals) are safe and effective.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Progestogen-Only and Emergency Contraception','easy','flashcard','How does the desogestrel POP (Cerazette 75 mcg) differ from traditional norethisterone POPs?','["Desogestrel POP reliably suppresses ovulation in ~97% of cycles — its primary mechanism. Traditional POPs (norethisterone 350 mcg) primarily work by thickening cervical mucus and do NOT reliably suppress ovulation. The desogestrel POP also has a 12-hour window for missed pills vs. 3 hours for traditional POPs."]','A','The desogestrel POP is effectively as reliable as the COCP for contraceptive efficacy due to consistent ovulation suppression, while remaining oestrogen-free. This makes it suitable for women who cannot take oestrogen.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Progestogen-Only and Emergency Contraception','easy','flashcard','What is the mechanism of action of levonorgestrel emergency contraception (e.g., Levonelle)?','["Primary mechanism: inhibition or delay of ovulation by preventing the LH surge. It is ineffective if ovulation has already occurred. It does NOT reliably prevent implantation (this mechanism is not supported by clinical evidence at standard doses). Must be taken within 72 hours for best efficacy; efficacy decreases with time."]','A','Levonorgestrel EC is not an abortifacient — it works before fertilisation by delaying or preventing ovulation. It has no effect on an established pregnancy.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Progestogen-Only and Emergency Contraception','medium','flashcard','How does ulipristal acetate work as emergency contraception and how does it differ from levonorgestrel?','["Ulipristal acetate (ellaOne) is a selective progesterone receptor modulator (SPRM). It inhibits or delays ovulation even after the LH surge has begun — something levonorgestrel cannot do. It is licensed for use up to 120 hours (5 days) post-intercourse vs. 72 hours for levonorgestrel. It may be more effective at >72 hours and in women with higher BMI."]','A','The key mechanistic distinction: ulipristal can act post-LH surge by delaying follicular rupture, giving it a wider and later window of efficacy. It should not be taken with hormonal contraceptives as they may mutually reduce efficacy.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Progestogen-Only and Emergency Contraception','medium','flashcard','Why is the copper IUD the most effective emergency contraceptive?','["The copper IUD is the most effective emergency contraceptive (>99% effective) when inserted within 5 days of unprotected intercourse. Copper ions are toxic to sperm (reducing motility and viability) and also toxic to the oocyte/embryo. It can also prevent implantation. It is effective regardless of body weight and can remain as ongoing contraception for up to 10 years."]','A','The copper IUD outperforms all oral emergency contraceptives in efficacy. It is particularly important to consider in women where oral ECs may be less effective (high BMI, late presentation >72 hours). Insertion requires a trained practitioner.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Progestogen-Only and Emergency Contraception','medium','flashcard','What counselling should be given to a woman taking ulipristal acetate (ellaOne) who also uses ongoing hormonal contraception?','["Ulipristal acetate interacts with hormonal contraception: progestogens in hormonal contraceptives may reduce ulipristal''s efficacy, and ulipristal may reduce progestogen receptor activity and contraceptive efficacy of ongoing hormonal methods. Advice: use barrier contraception for at least 5 days after taking ulipristal. If using combined pill, restart immediately but use condoms for 9 days."]','A','This interaction is clinically important and distinct from levonorgestrel EC which has no significant interaction with ongoing hormonal contraception. Women should receive clear written instructions.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Progestogen-Only and Emergency Contraception','easy','flashcard','List three groups of women for whom the progestogen-only pill is particularly appropriate.','["1. Breastfeeding women (oestrogen reduces milk supply; POP is safe). 2. Women with migraine with aura (oestrogen contraindicated due to stroke risk). 3. Women with history of VTE or thrombophilia (oestrogen is prothrombotic). Also appropriate in: cardiovascular disease, hypertension, diabetes with vascular complications, age >35 who smoke."]','A','The POP is often called the ''oestrogen-free'' option, making it suitable for all the contraindications to oestrogen. The desogestrel POP is the most effective POP formulation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Progestogen-Only and Emergency Contraception','hard','flashcard','What is the mechanism of action of the levonorgestrel-releasing intrauterine system (LNG-IUS, Mirena)?','["Local progestogenic effects: (1) Thickening of cervical mucus, preventing sperm penetration. (2) Endometrial atrophy, reducing the likelihood of implantation. (3) Possible suppression of ovulation in some cycles (~25%). Systemic absorption is minimal. The primary mechanisms are cervical mucus thickening and endometrial atrophy — NOT systemic ovulation suppression."]','A','The LNG-IUS is highly effective (>99%) and provides 5-8 years of contraception (depending on indication). Its local action explains why systemic progestogenic side effects are less pronounced than with systemic progestogen-only methods.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Progestogen-Only and Emergency Contraception','hard','flashcard','What drug interactions reduce the efficacy of the progestogen-only pill?','["Enzyme-inducing drugs accelerate progestogen metabolism via CYP3A4 induction, reducing plasma progestogen below contraceptive threshold. Key inducers: rifampicin, carbamazepine, phenytoin, phenobarbital, primidone, topiramate (high-dose), St John''s Wort. Women on enzyme inducers need alternative contraception (copper IUD preferred) or additional barrier methods during and for 28 days after stopping the inducer."]','A','Unlike the COCP, the POP is not affected by broad-spectrum antibiotics (non-enzyme-inducing). The enzyme-inducer interaction is the primary pharmacokinetic concern with the POP.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Progestogen-Only and Emergency Contraception','medium','flashcard','What is the missed pill rule for the norethisterone POP vs. the desogestrel POP?','["Norethisterone POP (traditional): missed if >3 hours late. Take missed pill immediately, use barrier contraception for 48 hours. Desogestrel POP (Cerazette): missed if >12 hours late. Take missed pill immediately, use barrier contraception for 48 hours. Both: if unprotected sex occurred during the missed pill period, consider emergency contraception."]','A','The extended 12-hour window for desogestrel POP makes it more forgiving for women with irregular schedules and is a practical advantage over traditional POPs.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Progestogen-Only and Emergency Contraception','easy','flashcard','What are the common side effects of the progestogen-only pill?','["Irregular, unpredictable bleeding (most common — amenorrhoea or frequent spotting). Acne. Headache. Breast tenderness. Mood changes. Slight weight change. Ovarian follicular cysts (usually resolve spontaneously). The desogestrel POP more often causes amenorrhoea; traditional POPs more often cause irregular spotting."]','A','Irregular bleeding is the leading reason women discontinue the POP. Counselling about expected bleeding patterns before starting is essential to improve adherence.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Fertility Drugs','medium','flashcard','What is the difference between recombinant FSH and human menopausal gonadotrophin (hMG) in fertility treatment?','["Recombinant FSH (follitropin alfa/beta, e.g., Gonal-F, Puregon): produced by recombinant DNA technology; contains only FSH; highly purified and consistent batch-to-batch. Human menopausal gonadotrophin (hMG, e.g., Menopur): urinary-derived from postmenopausal women''s urine; contains both FSH and LH activity (or FSH + hCG as LH surrogate). Clinical choice: hMG (FSH+LH) may be preferred in hypogonadotrophic hypogonadism (WHO Group I — no endogenous LH) where LH is needed for normal folliculogenesis. Recombinant FSH is generally preferred for PCOS (excess LH already present). Both are given by SC injection and have equivalent IVF outcomes in most women."]','A','The LH component in hMG is important for women with very low endogenous LH (hypogonadotrophic hypogonadism), as LH is needed for normal oestrogen production during follicular development. In PCOS, adding more LH (hMG) is usually unnecessary and may worsen androgen excess.','universal',false,'{year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Oxytocics and Uterotonics','easy','flashcard','What is the mechanism of action of oxytocin as a uterotonic?','["Oxytocin binds to Gq-coupled oxytocin receptors on myometrial smooth muscle cells. This activates phospholipase C → IP3 → release of calcium from the sarcoplasmic reticulum → myosin light chain kinase activation → smooth muscle contraction. Oxytocin receptor density increases progressively through pregnancy, peaking in labour, explaining increasing uterine sensitivity."]','A','Oxytocin produces rhythmic uterine contractions (unlike ergometrine which causes sustained tetanic contraction). For this reason, oxytocin is used for induction of labour (rhythmic) and for PPH (sustained infusion or IM bolus).','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Oxytocics and Uterotonics','easy','flashcard','Why is ergometrine avoided in women with hypertension or pre-eclampsia?','["Ergometrine stimulates alpha-adrenoceptors and 5-HT2 receptors in smooth muscle. In blood vessels, this causes vasoconstriction, which can precipitate or dramatically worsen hypertension. In women with pre-eclampsia, whose cerebral autoregulation is already impaired, this can cause hypertensive encephalopathy, stroke, or maternal death. Oxytocin alone is used instead."]','A','Syntometrine (ergometrine + oxytocin) is a first-line PPH prevention agent but is absolutely contraindicated in hypertensive women. This is a high-yield clinical distinction.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Oxytocics and Uterotonics','medium','flashcard','What are the advantages of misoprostol over other uterotonics for use in low-resource settings?','["Misoprostol (PGE1 analogue) advantages: (1) Heat-stable — does not require cold chain refrigeration unlike oxytocin. (2) Multiple routes — oral, sublingual, buccal, vaginal, rectal. (3) Cheap and widely available. (4) Can be self-administered. Disadvantages: lower efficacy than oxytocin for PPH; side effects include pyrexia, shivering, and diarrhoea."]','A','Misoprostol''s heat stability and oral/sublingual routes make it invaluable in settings without reliable refrigeration or IV access. The WHO recommends it for PPH prevention in low-resource settings.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Oxytocics and Uterotonics','medium','flashcard','What are the signs and management of oxytocin-induced water intoxication?','["Signs: headache, nausea, vomiting, confusion, drowsiness, seizures, coma. Hyponatraemia (Na+ <130 mmol/L) on blood tests. Cause: oxytocin has structural similarity to ADH and causes water retention at high doses, especially when given in large volumes of hypotonic fluid. Management: stop oxytocin infusion, restrict fluids, correct hyponatraemia cautiously (risk of central pontine myelinolysis with rapid correction)."]','A','Water intoxication is a rare but serious complication of high-dose IV oxytocin. It is more likely when oxytocin is mixed in 5% dextrose (hypotonic) rather than 0.9% saline. Using normal saline as the diluent reduces risk.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Oxytocics and Uterotonics','medium','flashcard','In which patient is carboprost (15-methyl PGF2-alpha) contraindicated and why?','["Carboprost is absolutely contraindicated in women with asthma. PGF2-alpha analogues cause bronchoconstriction via FP receptor stimulation in bronchial smooth muscle. In an asthmatic, this can trigger life-threatening bronchospasm. Alternative uterotonics for PPH in asthmatics: oxytocin, misoprostol (PGE1 causes bronchodilation), or tranexamic acid."]','A','This is a classic exam question. The FP receptor contrast with PGE1 receptors is important: PGF2-alpha causes bronchoconstriction, while PGE1 causes bronchodilation. Therefore misoprostol (PGE1) is safe in asthma.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Oxytocics and Uterotonics','hard','flashcard','What is the mechanism of tranexamic acid in PPH and what trial evidence supports its use?','["Tranexamic acid competitively inhibits plasminogen binding to fibrin by blocking lysine binding sites, preventing plasmin formation. This inhibits fibrinolysis, stabilising blood clots. The WOMAN trial (2017, 20,000+ women) showed that tranexamic acid given within 3 hours of delivery reduced PPH mortality by 31% and bleeding-related death by 19%, with no increase in VTE. It is now recommended by WHO and RCOG in all cases of PPH."]','A','The time-sensitivity is critical: WOMAN trial showed benefit only when given within 3 hours. After 3 hours there was no mortality benefit. This underpins the early administration recommendation in PPH protocols.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Oxytocics and Uterotonics','hard','flashcard','What is uterine hyperstimulation and how is it managed pharmacologically?','["Uterine hyperstimulation: excessive uterine contractions (>5 in 10 minutes) or contractions lasting >2 minutes, reducing uteroplacental blood flow and causing fetal distress (CTG changes). Management: (1) Stop oxytocin infusion or remove dinoprostone pessary. (2) Position woman in left lateral decubitus. (3) Administer tocolytic: terbutaline 250 mcg SC (beta-2 agonist) — first-line acute tocolysis for hyperstimulation. (4) Fetal resuscitation: high-flow oxygen, IV fluid bolus."]','A','Terbutaline SC is the pharmacological antidote to uterine hyperstimulation. It works within minutes to relax the uterus. This is distinct from its use as a sustained tocolytic for preterm labour (where nifedipine or atosiban is preferred).','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Oxytocics and Uterotonics','easy','flashcard','What are the components of Syntometrine and what are its indications?','["Syntometrine = oxytocin 5 units + ergometrine 500 micrograms in 1 mL, given by IM injection. Indication: active management of the third stage of labour (to prevent PPH). Oxytocin provides rapid onset uterine contraction; ergometrine provides prolonged sustained contraction. Contraindications: hypertension, pre-eclampsia, cardiovascular disease (due to ergometrine-induced vasoconstriction)."]','A','Active management of the third stage reduces PPH risk from ~15% to ~5%. Syntometrine reduces blood loss more than oxytocin alone but has more side effects (nausea, vomiting, hypertension).','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Oxytocics and Uterotonics','medium','flashcard','What is the step-wise pharmacological management of postpartum haemorrhage (PPH)?','["Step 1: Oxytocin IV bolus + infusion (first line). Step 2: Ergometrine IV or IM (if not hypertensive). Step 3: Syntometrine IM. Step 4: Carboprost IM 250 mcg every 15 min (max 8 doses) — avoid in asthma. Step 5: Misoprostol sublingual/rectal 800-1000 mcg. Step 6: Tranexamic acid IV 1g (give within 3 hours). Concurrent surgical measures if pharmacological treatment fails."]','A','PPH is defined as >500 mL blood loss after vaginal delivery or >1000 mL after caesarean. Knowing the stepped approach and contraindications of each agent is essential for OSCE and clinical practice.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Tocolytics','easy','flashcard','What is the primary goal of tocolytic therapy in preterm labour?','["The primary goal is NOT to permanently arrest preterm labour but to delay delivery by 24-48 hours. This window allows: (1) Administration of antenatal corticosteroids (betamethasone or dexamethasone) to accelerate fetal lung maturation. (2) Transfer to a tertiary centre with NICU facilities. Tocolytics do not significantly improve perinatal outcomes beyond this initial 48-hour window."]','A','This is a critical conceptual point. Tocolytics buy time — they are not a cure for preterm labour. The benefit comes from what is done during the delay (steroids, transfer), not from the prolongation of pregnancy itself.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Tocolytics','easy','flashcard','What is the mechanism of nifedipine as a tocolytic?','["Nifedipine is a dihydropyridine L-type calcium channel blocker. It blocks voltage-gated calcium channels in myometrial smooth muscle cells, preventing calcium influx. Reduced intracellular calcium → reduced myosin light chain kinase activation → reduced uterine contractility. It is widely used as first-line tocolytic in preterm labour due to good oral bioavailability, established evidence, and low cost."]','A','Nifedipine is preferred over beta-agonists for sustained tocolysis due to its favourable side-effect profile. It is given orally (immediate-release capsules initially, then modified-release). Main side effects: maternal hypotension, tachycardia, flushing, headache.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Tocolytics','medium','flashcard','What are the maternal side effects of beta-2 agonist tocolytics (e.g., salbutamol, ritodrine)?','["Cardiovascular: tachycardia, palpitations, chest pain, arrhythmias, pulmonary oedema (most serious — risk increases with prolonged use, steroids, and IV fluid). Metabolic: hyperglycaemia, hypokalaemia (beta-2 stimulation shifts K+ into cells). CNS: tremor, anxiety, headache. Fetal/neonatal: fetal tachycardia, neonatal hypoglycaemia (reactive to maternal hyperglycaemia). Due to these risks, beta-agonist tocolysis is now less preferred than nifedipine or atosiban."]','A','Pulmonary oedema is the most serious complication of beta-agonist tocolysis, particularly when combined with IV fluids and corticosteroids. Signs: breathlessness, hypoxia, bilateral crepitations. Management: stop beta-agonist, diuresis, oxygen.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Tocolytics','medium','flashcard','What is the mechanism and indication for magnesium sulphate as neuroprotection in preterm labour?','["MgSO4 given to mothers at risk of preterm birth <32 weeks reduces the risk of cerebral palsy and major motor dysfunction in surviving preterm neonates (Cochrane review: RR 0.68). Mechanism of neuroprotection: NMDA receptor antagonism (blocks glutamate-mediated excitotoxicity), reduction of cerebral vasospasm, stabilisation of neuronal membranes. It is given as 4g IV loading dose over 20-30 min, then 1g/hr maintenance."]','A','MgSO4 neuroprotection is distinct from its tocolytic and anticonvulsant uses. It is recommended by NICE and RCOG for women in established preterm labour or having planned preterm birth at <32 weeks.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Tocolytics','hard','flashcard','Why is indomethacin (a COX inhibitor) used as a tocolytic only before 32 weeks of gestation?','["Prostaglandins (PGE2 and PGI2) maintain ductus arteriosus patency in the fetus. Indomethacin inhibits COX-1 and COX-2, reducing prostaglandin synthesis. Before 32 weeks, the fetal ductus is less sensitive to this effect. After 32 weeks, COX inhibition significantly increases the risk of premature ductus arteriosus constriction → right ventricular hypertrophy → neonatal pulmonary hypertension. Oligohydramnios (via reduced fetal renal prostaglandins) is also a risk with prolonged use."]','A','Indomethacin is a highly effective tocolytic with good oral bioavailability but is restricted to <32 weeks and <48-72 hours of use due to fetal risks. Serial fetal echocardiography is recommended during treatment.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Tocolytics','hard','flashcard','What is the mechanism and clinical profile of atosiban as a tocolytic?','["Atosiban (Tractocile) is a competitive peptide antagonist at oxytocin receptors and vasopressin V1a receptors in the myometrium. By blocking oxytocin signalling, it reduces intracellular calcium and myometrial contractility. Given IV (bolus then infusion). Advantages over beta-agonists: fewer cardiovascular side effects (no maternal tachycardia/pulmonary oedema risk), no metabolic effects, suitable for diabetics. Disadvantage: expensive; evidence for superiority over nifedipine is limited."]','A','Atosiban is the preferred tocolytic in Europe (RCOG guidance) between 24+0 and 33+6 weeks. It is given by IV infusion in hospital. Its receptor selectivity is its main pharmacological advantage.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Tocolytics','easy','flashcard','What corticosteroids are given for fetal lung maturation in preterm labour and what is the dose?','["Betamethasone 12 mg IM in two doses 24 hours apart (preferred). OR Dexamethasone 6 mg IM in four doses 12 hours apart. Given between 24+0 and 34+6 weeks (consider up to 35+6). Mechanism: glucocorticoids induce surfactant synthesis (phosphatidylcholine) in fetal type II pneumocytes, reducing surface tension and preventing alveolar collapse. Reduces RDS risk by ~50%, IVH, NEC, and neonatal mortality."]','A','This is one of the most impactful interventions in obstetrics. Betamethasone is preferred over dexamethasone due to slightly better evidence. A single course is standard; repeat courses are controversial.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Tocolytics','medium','flashcard','What interaction occurs between nifedipine tocolysis and magnesium sulphate neuroprotection?','["Both drugs inhibit calcium-dependent processes. Nifedipine blocks voltage-gated calcium channels. Magnesium is a physiological calcium antagonist (competes with calcium at NMDA receptors and smooth muscle channels). Their combination can cause additive/synergistic cardiovascular and neuromuscular depression: severe hypotension, potentiation of neuromuscular blockade, respiratory depression, excessive uterine relaxation. Close monitoring of blood pressure, deep tendon reflexes, and respiratory rate is mandatory."]','A','When both agents are co-prescribed, reduced doses of each may be needed. The combination is sometimes unavoidable (preterm labour requiring both tocolysis and neuroprotection), making monitoring critical.','universal',false,'{year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Tocolytics','hard','flashcard','What are the absolute contraindications to tocolysis?','["Tocolysis is contraindicated when continuing the pregnancy poses greater risk than preterm delivery: (1) Acute fetal compromise (non-reassuring CTG, severe FGR). (2) Placental abruption with significant haemorrhage. (3) Pre-eclampsia or eclampsia (delivery often indicated). (4) Intrauterine infection/chorioamnionitis (delivery is the treatment). (5) Intrauterine fetal death. (6) Lethal fetal anomaly. (7) Maternal haemodynamic instability."]','A','Recognising when NOT to use tocolysis is as important as knowing when to use it. In chorioamnionitis, delaying delivery with tocolysis worsens maternal and fetal sepsis risk.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Drugs in Pregnancy','easy','flashcard','What is the teratogenic mechanism of sodium valproate and what dose-dependent risks does it carry?','["Valproate inhibits histone deacetylase (HDAC), disrupting gene expression during embryogenesis. It also depletes folate. Teratogenic effects are dose-dependent: neural tube defects (spina bifida — 1-2% risk, 10x background), cardiac defects, craniofacial abnormalities, hypospadias. Neurodevelopmental risks: reduced IQ (by average 8-10 points), autism spectrum disorder (3-4x increased risk). Risks highest in first trimester but neurodevelopment affected throughout pregnancy."]','A','Valproate is the most teratogenic commonly used antiepileptic. Women of childbearing potential must be on the Valproate Pregnancy Prevention Programme (VPPP) with reliable contraception and annual specialist review.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Drugs in Pregnancy','easy','flashcard','Why are ACE inhibitors and ARBs contraindicated in the second and third trimesters of pregnancy?','["ACE inhibitors and ARBs reduce fetal renal perfusion by blocking angiotensin II-mediated renal efferent arteriolar constriction, which is critical for maintaining fetal GFR. This causes fetal renal dysgenesis/tubular dysgenesis → oligohydramnios → pulmonary hypoplasia, limb contractures (Potter sequence), and hypocalvaria (underdeveloped skull bones). These complications constitute ACE inhibitor fetopathy. First-trimester exposure is less certain but should be avoided."]','A','The fetal kidney depends on angiotensin II to maintain perfusion unlike the adult kidney. Oligohydramnios from ACE inhibitor use can be detected on ultrasound. Safe antihypertensives in pregnancy include labetalol, nifedipine, and methyldopa.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Drugs in Pregnancy','medium','flashcard','What are the critical periods of fetal development and their relevance to drug teratogenicity?','["Pre-implantation (0-2 weeks): all-or-nothing effect — drug either kills embryo or has no effect. Organogenesis/embryonic period (weeks 3-8): highest teratogenic risk — organs are forming. Drug exposure here causes structural malformations. Fetal period (weeks 9-40): organs are growing and maturing. Drug exposure causes functional impairment, growth restriction, or premature closure of structures (e.g., ductus arteriosus with NSAIDs). CNS development continues throughout pregnancy and postnatally."]','A','The embryonic period (weeks 3-8) is when major structural malformations occur. Many women do not know they are pregnant during this time, highlighting the importance of preconception counselling for women on teratogenic drugs.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Drugs in Pregnancy','medium','flashcard','What folic acid doses are recommended in pregnancy and for which groups is the higher dose needed?','["Standard risk: 400 mcg (0.4 mg) daily from preconception until 12 weeks gestation. High risk (5 mg daily): previous pregnancy with NTD, personal/partner history of NTD, antiepileptic drugs (especially valproate, carbamazepine), type 1 or 2 diabetes, obesity (BMI >30), coeliac disease (folate malabsorption), sickle cell disease, on methotrexate (stop methotrexate 3 months before). Folic acid reduces NTD risk by ~70%."]','A','The difference in dose between standard and high-risk women is a classic exam question. The 5 mg dose provides greater folate supplementation to overcome deficiency states or increased folate metabolism from enzyme-inducing drugs.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Drugs in Pregnancy','medium','flashcard','What is warfarin embryopathy and when does it occur?','["Warfarin embryopathy results from warfarin exposure during weeks 6-12 of gestation (first trimester). Features: nasal hypoplasia (saddle nose deformity), stippled epiphyses on X-ray, ocular abnormalities (Dandy-Walker malformation, microcephaly). Mechanism: warfarin inhibits vitamin K-dependent gamma-carboxylation of osteocalcin and matrix Gla protein, disrupting bone and cartilage formation. In 2nd/3rd trimesters: fetal intracranial haemorrhage risk."]','A','Heparin (unfractionated or LMWH) does not cross the placenta and is the anticoagulant of choice throughout pregnancy. Warfarin may be considered in some mechanical heart valve patients (risk-benefit discussion) but under specialist care.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Drugs in Pregnancy','hard','flashcard','What drugs are considered safe to use throughout pregnancy for common conditions?','["Analgesics: paracetamol (preferred throughout). Antacids: antacids (calcium carbonate), H2 blockers (ranitidine — caution, omeprazole with caution). Antibiotics: penicillins (amoxicillin, co-amoxiclav), erythromycin, cephalosporins, nitrofurantoin (avoid near term — risk of neonatal haemolysis). Antihypertensives: labetalol, methyldopa, nifedipine. Antiemetics: cyclizine, promethazine, prochlorperazine, ondansetron (2nd/3rd trimester). Anticoagulants: LMWH (heparin). Antiepileptics: lamotrigine or levetiracetam (lower teratogenic risk)."]','A','Knowledge of safe drugs in pregnancy is clinically essential. The mantra is ''use the lowest effective dose of the safest available drug.'' All prescribing in pregnancy involves a risk-benefit analysis.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Drugs in Pregnancy','easy','flashcard','What fetal cardiac malformation is associated with lithium use in the first trimester?','["Ebstein anomaly — a rare congenital tricuspid valve abnormality where the tricuspid leaflets are displaced apically into the right ventricle, causing tricuspid regurgitation, right heart enlargement, and (in severe cases) cyanosis and arrhythmias. The absolute risk is small (~1 in 1000-2000 exposures) but elevated ~2-3x above background. Lithium should be avoided in the first trimester where possible, or a careful risk-benefit discussion held with the patient."]','A','Ebstein anomaly = lithium. This association is tested frequently. Other cardiac teratogens: alcohol (VSD, ASD), phenytoin (pulmonary stenosis, VSD), and retinoic acid derivatives (conotruncal defects).','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Drugs in Pregnancy','hard','flashcard','Why is low-dose aspirin (75-150 mg) used from early pregnancy in high-risk women and what is its mechanism?','["Aspirin at low doses preferentially inhibits platelet COX-1, reducing thromboxane A2 (pro-aggregant, vasoconstrictive) more than endothelial prostacyclin (anti-aggregant, vasodilatory). This shifts the balance toward vasodilation and reduced platelet aggregation in the placental vasculature, improving uteroplacental blood flow and reducing the risk of pre-eclampsia. Started before 16 weeks (ideally by 12 weeks) in high-risk women. Evidence: ASPRE trial (2017) showed 62% reduction in pre-term pre-eclampsia."]','A','High-risk criteria: previous pre-eclampsia, chronic hypertension, pre-gestational diabetes, multiple pregnancy, CKD, antiphospholipid syndrome. Moderate risk: nulliparity, BMI >35, age >40, family history, IVF pregnancy. Those with ≥2 moderate risk factors also qualify.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Drugs in Pregnancy','medium','flashcard','Which antibiotics are contraindicated in pregnancy and why?','["Tetracyclines (all trimesters): chelate calcium → inhibit bone development, discolour deciduous teeth (2nd/3rd trimester). Trimethoprim (1st trimester): folate antagonist → neural tube defects risk. Fluoroquinolones (ciprofloxacin): arthropathy risk (cartilage effects in animal studies; avoid on precautionary principle). Chloramphenicol (near term): ''grey baby syndrome'' (neonatal cardiovascular collapse) — immature liver cannot glucuronidate chloramphenicol. Nitrofurantoin (near term): neonatal haemolysis."]','A','Tetracyclines are probably the most commonly tested antibiotic contraindication in pregnancy. The calcium chelation mechanism is key. Safe alternatives for most indications: amoxicillin, cephalosporins, erythromycin.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Pre-eclampsia Management','easy','flashcard','What is the first-line antihypertensive for acute severe hypertension (BP ≥160/110 mmHg) in pre-eclampsia?','["Labetalol — given orally (200 mg) or IV (50 mg bolus over 1 minute, repeated every 5 minutes to a maximum of 200 mg total, OR as IV infusion 20-160 mg/hour). It is a combined alpha-1 and non-selective beta blocker. The alpha-1 blockade reduces peripheral vascular resistance; beta blockade reduces heart rate. Second-line: oral nifedipine MR 10-20 mg. Third-line: IV hydralazine. ACE inhibitors and ARBs are contraindicated."]','A','The target BP in severe pre-eclampsia is <150/100 mmHg. Acute BP ≥160/110 is a hypertensive emergency requiring treatment within 30-60 minutes to prevent maternal stroke.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Pre-eclampsia Management','easy','flashcard','What is the standard magnesium sulphate regimen for eclampsia prevention?','["Loading dose: 4 g IV over 5-10 minutes. Maintenance: 1 g/hour IV infusion, continued for 24 hours after delivery or after last seizure. If seizure occurs during treatment (breakthrough seizure): additional 2-4 g IV bolus over 5 minutes. Therapeutic range: 2-4 mmol/L serum magnesium. Monitoring: deep tendon reflexes (hourly), urine output (>25 mL/hour), respiratory rate (>12/min), oxygen saturation."]','A','Magnesium sulphate is superior to phenytoin and diazepam for prevention and treatment of eclamptic seizures (Magpie trial, 2002). It must not be confused with magnesium for neuroprotection (which uses the same dose regimen but different indication).','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Pre-eclampsia Management','medium','flashcard','What are the signs of magnesium sulphate toxicity and what is the antidote?','["Signs in order of increasing toxicity: (1) Loss of deep tendon reflexes (patellar reflex) — at ~5 mmol/L. (2) Respiratory depression (<12 breaths/min) — at ~7 mmol/L. (3) Cardiac conduction abnormalities and arrest — at >12 mmol/L. (4) Neuromuscular paralysis. Antidote: Calcium gluconate 10 mL of 10% solution IV over 3 minutes (calcium directly antagonises magnesium). Stop the MgSO4 infusion immediately."]','A','Deep tendon reflex monitoring is the clinical proxy for magnesium toxicity — reflexes are lost before respiratory depression and cardiac toxicity. This is why HOURLY reflex checks are a protocol requirement during MgSO4 infusion.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Pre-eclampsia Management','medium','flashcard','What is the mechanism of action of methyldopa as an antihypertensive in pregnancy?','["Methyldopa is a prodrug. After absorption, it is decarboxylated and hydroxylated in the CNS to alpha-methylnoradrenaline. This acts as an alpha-2 adrenoceptor agonist in the brainstem (nucleus tractus solitarius), reducing central sympathetic outflow → decreased peripheral vascular resistance and heart rate → lowered blood pressure. It has the longest safety record in pregnancy of any antihypertensive. Main side effects: sedation, depression, autoimmune haemolytic anaemia (long-term)."]','A','Methyldopa is safe in all trimesters but is sedating and can cause depression with long-term use. It is often used for chronic hypertension in pregnancy when nifedipine is insufficient. It is not a first-line agent for acute hypertension.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Pre-eclampsia Management','hard','flashcard','What is the pharmacological rationale for using magnesium sulphate rather than benzodiazepines to treat eclamptic seizures?','["MgSO4 is preferred over benzodiazepines (diazepam) for eclampsia because: (1) Superior efficacy: Collaborative Eclampsia Trial showed 52% less recurrent seizures vs. diazepam. (2) Does not cause maternal CNS/respiratory depression at therapeutic doses (diazepam causes sedation and neonatal respiratory depression). (3) Does not cause neonatal CNS depression (diazepam crosses placenta and causes neonatal hypotonia, respiratory depression, hypothermia — ''floppy infant syndrome''). (4) Addresses cerebrovascular mechanism (NMDA antagonism, vasodilation) not just seizure suppression."]','A','The Collaborative Eclampsia Trial (1995) established MgSO4 superiority. Diazepam is only used if MgSO4 is unavailable or if there are specific contraindications to magnesium (severe renal failure).','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Pre-eclampsia Management','hard','flashcard','What is the pathophysiological basis of pre-eclampsia that informs antihypertensive drug selection?','["Pre-eclampsia involves abnormal placentation with failure of trophoblast invasion → hypoperfused placenta releases antiangiogenic factors (sFlt-1/soluble VEGF receptor, soluble endoglin) into maternal circulation → widespread maternal endothelial dysfunction → vasoconstriction, hypertension, proteinuria, end-organ damage. This explains why antihypertensives treat the symptoms but NOT the cause. Only delivery (removing the placenta) cures pre-eclampsia. Drugs that increase uteroplacental flow (NO donors, sildenafil) have been researched but not proven beneficial."]','A','Understanding the antiangiogenic mechanism explains why BP control merely reduces stroke risk — it does not treat the underlying disease. Research into sFlt-1 levels for diagnosis and targeted therapy (plasma exchange to remove sFlt-1) is ongoing.','universal',true,'{year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Pre-eclampsia Management','medium','flashcard','Why is atenolol avoided in pregnancy-related hypertension?','["Atenolol is associated with fetal growth restriction (FGR/IUGR) when used in pregnancy, particularly when started in the first or second trimester. Beta-1 blockade reduces maternal cardiac output and may reduce uteroplacental blood flow. Unlike labetalol (combined alpha/beta blocker), which has alpha-1-mediated vasodilation partially compensating for reduced cardiac output, atenolol has no vasodilatory component. NICE recommends against atenolol in pregnancy."]','A','Labetalol is acceptable in pregnancy; atenolol is not. This distinction is clinically important and frequently tested. Other beta-blockers (metoprolol, bisoprolol) are used with caution in pregnancy when necessary but are not first-line.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Pre-eclampsia Management','easy','flashcard','What parameters must be monitored during magnesium sulphate infusion?','["The '4 Bs' monitoring: (1) Blood pressure — ongoing hypertension monitoring. (2) Breathing — respiratory rate must remain >12 breaths/min. (3) Bends (reflexes) — deep tendon (patellar) reflex must be present. (4) Blood/Bore — urine output >25 mL/hour (magnesium is renally excreted; oliguria → accumulation → toxicity). Serum magnesium levels can be checked if toxicity suspected. Oxygen saturation monitoring is also recommended."]','A','This monitoring ensures early detection of toxicity. Magnesium is exclusively renally excreted, so renal failure greatly increases toxicity risk. In significant renal impairment, dose reduction and more frequent serum level monitoring are needed.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Fertility Drugs','easy','flashcard','What is the mechanism of action of clomiphene citrate for ovulation induction?','["Clomiphene is a selective oestrogen receptor modulator (SERM) acting as an oestrogen antagonist at hypothalamic oestrogen receptors. By blocking oestrogen negative feedback, GnRH pulse frequency increases → elevated pituitary FSH and LH → stimulation of follicular development and ovulation. Given orally day 2-6 of the menstrual cycle. Starting dose 50 mg, increase to 100 mg if no response. Effective in WHO Group II anovulation (PCOS)."]','A','Clomiphene works by reducing oestrogen signalling at the hypothalamus, not the ovary directly. Its anti-oestrogenic effect on cervical mucus and endometrium can reduce efficacy despite successful ovulation — a limitation. Multiple pregnancy rate ~10% (mainly twins).','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Fertility Drugs','medium','flashcard','What is ovarian hyperstimulation syndrome (OHSS) and how is it prevented?','["OHSS is a potentially life-threatening iatrogenic complication of ovarian stimulation, characterised by massive ovarian enlargement, ascites, pleural effusion, haemoconcentration (raised haematocrit), and thromboembolic risk. Mediated by VEGF causing increased vascular permeability. Risk factors: PCOS, young age, low BMI, high antral follicle count, high AMH. Prevention: GnRH antagonist protocol, trigger ovulation with GnRH agonist instead of hCG (in antagonist cycles), cabergoline (dopamine agonist reduces VEGF signalling), elective freeze-all strategy, follicle number limitation."]','A','OHSS management: mild — monitor; moderate — IV fluids, thromboprophylaxis; severe — hospital admission, paracentesis, IV albumin. GnRH antagonist protocols significantly reduce OHSS risk versus long agonist protocols.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Fertility Drugs','medium','flashcard','How does bromocriptine treat infertility due to hyperprolactinaemia?','["Bromocriptine is an ergot-derived dopamine D2 agonist. Dopamine is the physiological inhibitor (prolactin inhibitory factor) of pituitary lactotroph cells. By mimicking dopamine, bromocriptine suppresses prolactin secretion. Elevated prolactin causes anovulation by disrupting GnRH pulsatility and directly inhibiting LH/FSH release. By reducing prolactin to normal, pulsatile GnRH resumes → normal LH/FSH → ovulation restored. Cabergoline (longer half-life, better tolerated) is now preferred."]','A','Hyperprolactinaemia is the most common treatable cause of anovulatory infertility. Common causes: prolactinoma, antipsychotics (dopamine antagonists), hypothyroidism. Exclusion of secondary causes before starting dopamine agonists is important.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Fertility Drugs','hard','flashcard','Compare the mechanisms of GnRH agonists and GnRH antagonists in IVF protocols.','["GnRH agonists (buserelin, leuprorelin): peptide analogues given SC/intranasally. Continuous non-pulsatile stimulation causes initial LH/FSH flare (1-2 weeks) then receptor downregulation/desensitisation → prolonged FSH/LH suppression (chemical castration). Used in long protocols: ~2 weeks of downregulation before starting gonadotrophins. Disadvantage: flare risk in cancer patients, prolonged treatment, menopausal symptoms. GnRH antagonists (cetrorelix, ganirelix): immediately and competitively block GnRH receptors. Rapid, dose-dependent, reversible FSH/LH suppression without flare. Used in short antagonist protocols (5-6 days total). Advantages: shorter, less expensive, lower OHSS risk."]','A','The antagonist protocol is now the standard IVF approach in many centres due to lower OHSS risk and shorter duration. The agonist protocol may be preferred in certain patient groups (e.g., poor responders using the agonist flare for stimulation).','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Fertility Drugs','easy','flashcard','What is the role of hCG (human chorionic gonadotrophin) in fertility treatment?','["hCG has the same receptor as LH (LH/CG receptor). Uses: (1) Trigger shot for final oocyte maturation in IVF — given 34-36 hours before egg retrieval to mimic the LH surge. (2) Luteal phase support — injections of hCG support corpus luteum function, increasing progesterone. (3) Male infertility — hCG stimulates testicular Leydig cells to produce testosterone and supports spermatogenesis (with FSH). Main risk: precipitating OHSS (hCG has a longer half-life than LH and provides prolonged receptor stimulation)."]','A','The hCG trigger can be replaced with a GnRH agonist trigger in antagonist protocols to reduce OHSS risk (GnRH agonist causes a brief, self-limited FSH/LH surge instead of prolonged hCG stimulation).','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Fertility Drugs','medium','flashcard','Why is letrozole (an aromatase inhibitor) used for ovulation induction in PCOS?','["Letrozole inhibits aromatase (CYP19A1), blocking conversion of androgens to oestrogens. Low oestrogen removes negative feedback on the hypothalamus/pituitary → increased GnRH and FSH → mono-follicular development. Advantages over clomiphene in PCOS: (1) No anti-oestrogenic effect on cervical mucus or endometrium. (2) Shorter half-life → oestrogen recovery sooner after drug stopped → better endometrial receptivity. (3) Higher live birth rates (PPCOSII trial, 2014). (4) Lower multiple pregnancy rate."]','A','Letrozole is now considered first-line for ovulation induction in PCOS in many guidelines (ESHRE 2023), despite initially being off-label. It is not licensed for fertility use in the UK but is widely used off-label.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Fertility Drugs','hard','flashcard','What is the initial testosterone flare with GnRH agonists in prostate cancer and how is it managed in fertility contexts?','["In fertility: GnRH agonists cause an initial ''flare'' with a surge in LH and FSH over the first 7-14 days of administration before receptor downregulation occurs. In IVF long protocols, this flare is expected and deliberately timed. Some fertility specialists use a short ''flare'' protocol in poor responders to exploit this initial gonadotrophin surge to improve ovarian response. In prostate cancer: the testosterone flare can worsen disease — managed by co-prescribing an anti-androgen (bicalutamide) for the first 4 weeks to block the testosterone effect at target tissues."]','A','The flare is mechanistically identical in fertility and oncology contexts but is exploited positively in fertility (short flare protocol) and mitigated negatively in oncology (anti-androgen cover). Understanding this distinction demonstrates deep mechanistic understanding.','universal',false,'{year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Fertility Drugs','easy','flashcard','What is metformin''s role in fertility treatment for women with PCOS?','["Metformin reduces insulin resistance, lowering fasting insulin and IGF-1. This reduces ovarian androgen production (which is insulin/LH-driven) and can restore menstrual regularity and spontaneous ovulation in some PCOS women. In IVF, metformin reduces OHSS risk (by improving insulin sensitivity and reducing IGF-1 → lower VEGF). It is used as an adjunct to clomiphene or letrozole, not as a primary fertility agent. It does not directly stimulate follicular development."]','A','Metformin alone restores ovulation in approximately 30-40% of PCOS women. It is most beneficial in insulin-resistant PCOS (obese women with high fasting insulin). It does not improve IVF outcomes unless given to reduce OHSS.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','HRT','easy','flashcard','Why must women with an intact uterus take combined (oestrogen + progestogen) HRT?','["Unopposed oestrogen stimulates endometrial proliferation. Continuous oestrogen exposure without progesterone-mediated opposition leads to endometrial hyperplasia → atypical hyperplasia → endometrial carcinoma. Adding progestogen opposes oestrogenic endometrial proliferation, causing endometrial atrophy and preventing this progression. Women without a uterus (post-hysterectomy) can safely take oestrogen-only HRT without progestogen."]','A','This is the fundamental rationale for combined HRT. The choice of progestogen type affects the risk: synthetic progestogens (MPA — associated with increased breast cancer in WHI trial) vs. micronised progesterone (appears to have a lower breast cancer and VTE risk).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','HRT','easy','flashcard','What are the main benefits of HRT for menopausal symptoms?','["Vasomotor symptoms: reduces hot flushes and night sweats by 90% (most effective treatment available). Genitourinary symptoms: improves vaginal atrophy, dryness, dyspareunia, recurrent UTIs. Mood: reduces depressive symptoms associated with the menopause. Sleep: improves sleep quality secondary to reduced night sweats. Bone: prevents postmenopausal osteoporosis and fractures. Sexual function: improves libido (especially with added testosterone). Skin: slows collagen loss."]','A','HRT is the most effective treatment for vasomotor symptoms. Non-hormonal alternatives (SSRIs, venlafaxine, clonidine, gabapentin) are only ~50% as effective as HRT and are options when HRT is contraindicated.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','HRT','medium','flashcard','Why does transdermal oestrogen carry a lower VTE risk than oral oestrogen in HRT?','["Oral oestrogen undergoes first-pass hepatic metabolism, stimulating hepatic synthesis of pro-coagulant factors (VII, VIII, X, fibrinogen) and reducing anticoagulant proteins (protein C, S, antithrombin). This net prothrombotic shift increases VTE risk 2-4-fold. Transdermal oestrogen (patches, gel, spray) bypasses the portal circulation and liver, producing physiological blood oestradiol levels without activating hepatic clotting factor synthesis. Transdermal oestrogen does not increase VTE risk above baseline in women without other risk factors."]','A','This pharmacokinetic distinction (first-pass hepatic metabolism avoided by transdermal route) is a key exam concept. It is why transdermal HRT is preferred in women with VTE risk factors, thrombophilia, obesity, or migraine.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','HRT','medium','flashcard','What were the key findings and limitations of the WHI trial regarding HRT?','["WHI trial (2002): Combined oestrogen (conjugated equine) + medroxyprogesterone acetate in women aged 50-79 (mean 63). Findings: increased breast cancer (HR 1.26), increased VTE (HR 2.11), increased stroke (HR 1.41). Coronary events increased in older women (>60 or >10 years post-menopause). Limitations: Used older women (not representative of HRT users who start at menopause), used oral conjugated oestrogen + MPA (not modern transdermal/micronised progesterone), overestimated breast cancer risk (7 extra cases per 10,000 women per year — absolute risk small). The WHI findings do not apply equally to all HRT formulations or to younger women."]','A','The ''timing hypothesis'' (or ''window of opportunity''): HRT started close to menopause onset (within 10 years/age <60) appears to have cardiovascular benefit, not harm. The WHI design largely studied a different population.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','HRT','hard','flashcard','What is raloxifene and how does its receptor selectivity profile make it useful in postmenopausal women?','["Raloxifene is a second-generation SERM (selective oestrogen receptor modulator). Tissue effects: AGONIST at bone oestrogen receptors (maintains BMD, reduces vertebral fractures by ~30-50%), ANTAGONIST at breast tissue (reduces breast cancer risk by ~50%), ANTAGONIST at uterus (no endometrial stimulation — can be used without progestogen). ANTAGONIST at hypothalamus (does not reduce hot flushes — may worsen them). It increases VTE risk. Licensed for: osteoporosis prevention/treatment, breast cancer risk reduction in high-risk women."]','A','Raloxifene vs. tamoxifen: both are SERMs reducing breast cancer risk, but tamoxifen stimulates the endometrium (increasing endometrial cancer risk) whereas raloxifene is endometrium-neutral. Tamoxifen is used in pre- and postmenopausal women; raloxifene only in postmenopausal women.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','HRT','hard','flashcard','What is tibolone and how does it differ from conventional HRT?','["Tibolone is a synthetic steroid with mixed oestrogenic, progestogenic, and weak androgenic activity. It is converted in peripheral tissues to metabolites with tissue-selective activity: oestrogenic metabolites in bone and CNS (reduces hot flushes, maintains BMD), progestogenic/androgenic activity in endometrium (atrophic — does not stimulate, so no added progestogen needed even with intact uterus). Its androgenic component can improve libido. It does not stimulate breast tissue like conventional HRT. Disadvantage: slightly increased stroke risk in older women (>60) in LIFT trial."]','A','Tibolone is an alternative for women who find conventional HRT causes problematic breast tenderness or who wish to avoid separate progestogen. Its unique pharmacology (tissue-selective conversion) gives it a different benefit/risk profile from standard HRT.','universal',false,'{year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','HRT','medium','flashcard','What are the absolute contraindications to systemic HRT?','["1. Current or recent breast cancer (ER+ tumour — oestrogen may stimulate residual cells). 2. Endometrial cancer (oestrogen-dependent). 3. Active or recent VTE or arterial thromboembolic disease (unless on anticoagulation — specialist review needed). 4. Undiagnosed vaginal bleeding. 5. Untreated endometrial hyperplasia. 6. Active liver disease (impaired drug metabolism, liver unable to metabolise oestrogen). 7. Pregnancy. Note: local vaginal oestrogen is safer and has fewer systemic contraindications (minimal absorption)."]','A','These contraindications relate primarily to the oestrogen component. Breast cancer history is the most frequently tested. Vaginal oestrogen (pessaries/cream/ring) is generally considered safe even in many breast cancer survivors (specialist guidance needed).','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','HRT','easy','flashcard','What non-hormonal alternatives exist for menopausal vasomotor symptoms?','["1. SSRIs/SNRIs: venlafaxine (most evidence), paroxetine, escitalopram — reduce hot flushes by ~50%. 2. Gabapentin/pregabalin: reduce hot flushes, particularly nocturnal. 3. Clonidine (alpha-2 agonist): modest efficacy (~25% reduction). 4. Oxybutynin: anticholinergic, some evidence for hot flushes. 5. Fezolinetant: neurokinin B receptor antagonist — new, approved 2023, specifically targets KNDy neuron pathway causing hot flushes. Lifestyle: avoiding triggers (alcohol, caffeine, spicy food), layered clothing, cooling fans."]','A','Non-hormonal options are important for women in whom HRT is contraindicated (e.g., ER+ breast cancer survivors). Fezolinetant is the first non-hormonal drug targeting the specific neural pathway of hot flushes (neurokinin B signalling in the hypothalamus).','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Drugs for Gynaecological Conditions','easy','flashcard','What is the mechanism of mifepristone and how is it used in medical termination of pregnancy?','["Mifepristone (RU-486) is a competitive antagonist at progesterone receptors (and glucocorticoid receptors). By blocking progesterone, it: (1) Removes progesterone-mediated uterine quiescence (the ''progesterone block'' of labour). (2) Induces endometrial decidual breakdown. (3) Sensitises the myometrium and cervix to prostaglandins. Regimen: mifepristone 200 mg orally, followed 24-48 hours later by misoprostol (PGE1) 800 mcg vaginally/sublingually. Together they achieve complete uterine evacuation in ~95% of cases up to 10 weeks."]','A','The combination of mifepristone (anti-progesterone) + misoprostol (prostaglandin) is highly effective and is the standard regimen for medical TOP worldwide. The two drugs synergise: mifepristone primes the uterus to respond to prostaglandin.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Drugs for Gynaecological Conditions','easy','flashcard','Why are GnRH agonists effective for endometriosis treatment?','["Endometriosis is an oestrogen-dependent condition. Endometriotic deposits have oestrogen receptors and grow in response to cyclical oestrogen fluctuations. GnRH agonists (leuprorelin, buserelin, goserelin) create a hypoestrogenic state (''medical menopause'') by downregulating pituitary GnRH receptors, suppressing LH/FSH, and thus reducing ovarian oestrogen production. Without oestrogenic stimulation, endometriotic deposits atrophy and become inactive → symptom relief. Treatment is limited to 6 months due to bone loss from hypoestrogenism; add-back HRT can extend duration."]','A','GnRH agonists are highly effective for endometriosis but cause reversible bone loss (3-5% in 6 months). Recurrence is common after stopping. They are used pre-operatively (reduce deposit size) or as medical management where surgery is inappropriate.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Drugs for Gynaecological Conditions','medium','flashcard','What is the mechanism of tranexamic acid for heavy menstrual bleeding?','["The endometrium has a high fibrinolytic activity; during menstruation, increased plasminogen activator activity dissolves clots in endometrial vessels, contributing to heavy blood loss. Tranexamic acid competitively blocks lysine binding sites on plasminogen, preventing its conversion to plasmin → preserves fibrin clots in uterine vessels → reduces blood loss by approximately 40-50%. Taken only during heavy bleeding days (not throughout cycle). It is the first-line pharmacological treatment for HMB without an identified hormonal cause."]','A','Tranexamic acid is antifibrinolytic, not hormonal. It does not affect the menstrual cycle or fertility. It is taken at the start of menstruation and stopped when flow decreases. No significant systemic side effects at standard doses.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Drugs for Gynaecological Conditions','medium','flashcard','What are the side effects and limitations of danazol in endometriosis treatment?','["Danazol is a synthetic 17-alpha ethinyl testosterone derivative with weak androgenic, anti-oestrogenic, and anti-progestogenic activity. It suppresses the HPO axis (reducing LH/FSH) and has direct androgen receptor activity. Side effects from androgenicity: acne, oily skin, hirsutism, voice deepening (potentially irreversible), clitoromegaly, weight gain, adverse lipid changes (reduced HDL). Also: hepatotoxicity (monitor LFTs). Limitations: androgenic side effects limit acceptability; largely replaced by GnRH agonists and progestogens. Teratogenic — effective contraception mandatory during use."]','A','Danazol is rarely used now due to its androgenic side effect profile. However, it may still be used for cyclical breast pain (mastalgia) at lower doses where its anti-oestrogenic activity is beneficial.','universal',false,'{year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Drugs for Gynaecological Conditions','hard','flashcard','What is the mechanism of ulipristal acetate (Esmya) for uterine fibroids and what safety concern led to restrictions?','["Ulipristal acetate (Esmya 5 mg) is a selective progesterone receptor modulator (SPRM). Its actions on fibroids: (1) Antiproliferative and pro-apoptotic effects on fibroid smooth muscle cells via PR-A modulation. (2) Endometrial effect: causes specific histological changes (PAEC — progesterone receptor modulator-associated endometrial changes) — distinct from hyperplasia, reversible. (3) Reduces fibroid volume by 25-50% and controls HMB. Safety concern: cases of serious liver injury including acute liver failure requiring transplantation reported in post-marketing surveillance. EMA (2020) recommended suspension then restriction to acute pre-operative use only with mandatory LFT monitoring."]','A','The liver toxicity signal led to significant restrictions. The mechanism of hepatotoxicity is unknown. This case illustrates how post-marketing surveillance can change a drug''s risk profile long after licensing.','universal',false,'{year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Drugs for Gynaecological Conditions','hard','flashcard','How does elagolix differ from older GnRH-based treatments for endometriosis?','["Elagolix (Orilissa) is an oral, non-peptide, small-molecule GnRH receptor antagonist. Differences from GnRH agonists (e.g., leuprorelin): (1) Immediate action: competitively blocks GnRH receptors — no initial flare. (2) Oral formulation (GnRH agonists require SC injection or nasal spray). (3) Dose-dependent, partially reversible suppression: lower dose (150 mg OD) partially suppresses oestrogen; higher dose (200 mg BD) more complete suppression — allows titration. (4) Faster recovery of menstrual cycles after stopping. Disadvantages: VTE risk similar to other GnRH suppression; bone density effects dose-dependent."]','A','Elagolix represents a new class of oral GnRH antagonists. Its advantage over older GnRH agonists is the absence of the initial flare, oral route, and dose-dependent partial suppression. Approved by FDA for endometriosis pain, under review in other jurisdictions.','universal',false,'{year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Drugs for Gynaecological Conditions','medium','flashcard','What is the pharmacological management of heavy menstrual bleeding (first-line options)?','["Non-hormonal: (1) Levonorgestrel-releasing IUS (Mirena) — most effective (reduces blood loss by 80%+; NICE first-line if contraception also desired). (2) Tranexamic acid (antifibrinolytic, 40-50% reduction, taken during menstruation). (3) NSAIDs (e.g., mefenamic acid — reduce blood loss by 20-25% via prostaglandin inhibition + analgesic). Hormonal: (4) Combined oral contraceptive pill. (5) Progestogen-only (norethisterone, desogestrel, medroxyprogesterone). (6) GnRH agonists (for fibroids, short-term)."]','A','The LNG-IUS is the most cost-effective and efficacious long-term medical treatment for HMB and is NICE first-line for women without contraindications. Treatment choice depends on desire for fertility, contraception, and underlying cause.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Drugs for Gynaecological Conditions','easy','flashcard','What progestogen is used for medical management of endometrial cancer?','["High-dose progestogens (e.g., medroxyprogesterone acetate 200-500 mg/day, or megestrol acetate) oppose endometrial oestrogenic stimulation and have direct antiproliferative effects on endometrial cells via progesterone receptors (PR). Used in: (1) Early-stage, well-differentiated endometrial cancer in women wishing to preserve fertility (grade 1, stage IA). (2) Women unfit for surgery (medical comorbidities). Response rate ~25-35% in early disease. Must have PR-positive tumour for response. LNG-IUS can also deliver local progesterone to the endometrium."]','A','Progestogen therapy for endometrial cancer is fertility-sparing but not curative. Hysteroscopic surveillance and endometrial biopsy are mandatory to monitor response. It is not standard for advanced or grade 3 disease.','universal',false,'{year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Drugs for Gynaecological Conditions','hard','flashcard','Why do GnRH agonist-induced fibroids regrow after stopping treatment?','["Uterine fibroids (leiomyomata) overexpress oestrogen receptors (ER) and progesterone receptors (PR). GnRH agonists suppress ovarian oestrogen and progesterone production, creating a hypoestrogenic environment. Without hormonal stimulation, fibroids lose their trophic signals, becoming ischaemic → volume reduction of 20-50%. However, GnRH agonists do not eliminate the fibroid stem cells nor permanently alter the ER/PR expression. When oestrogen levels recover post-treatment (resumption of ovarian function), the remaining fibroid cells regrow → return to pre-treatment volume within 3-6 months. This is why GnRH agonists are used as a bridge to surgery, not definitive treatment."]','A','Add-back HRT (low-dose oestrogen + progestogen) during long-term GnRH agonist treatment can mitigate bone loss and menopausal symptoms without fully reversing fibroid shrinkage. However, it limits the degree of shrinkage achieved.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Prostate and Androgen Pharmacology','easy','flashcard','What is the mechanism and clinical benefit of alpha-1 blockers in BPH?','["Alpha-1A adrenoceptors are the predominant subtype in prostatic smooth muscle and bladder neck. Alpha-1 blockers (tamsulosin, alfuzosin, doxazosin, prazosin) block these receptors, relaxing smooth muscle and reducing urethral resistance → improved urinary flow rate (Qmax) and reduced symptoms (LUTS) within 24-48 hours. They do NOT reduce prostate volume. Tamsulosin is alpha-1A selective (uroselective) — less postural hypotension than non-selective agents. Side effects: postural hypotension (especially first dose), retrograde ejaculation (alpha-1 blockade in bladder neck), dizziness."]','A','Alpha-1 blockers work rapidly and are the most commonly used first-line drugs for BPH symptoms. They improve urinary flow but do not alter the natural history of BPH or prevent urinary retention. Retrograde ejaculation occurs in up to 30% of men.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Prostate and Androgen Pharmacology','easy','flashcard','What is the difference between finasteride and dutasteride for BPH?','["Finasteride: selective inhibitor of 5-alpha reductase type II (main isoform in prostate stroma). Reduces DHT by ~70%. Dose: 5 mg daily (BPH) or 1 mg daily (alopecia). Dutasteride: dual inhibitor of 5-alpha reductase type I AND type II. Reduces DHT by >90%. Dose: 0.5 mg daily. Clinical differences: Dutasteride achieves greater DHT suppression. Both take 3-6 months for clinical benefit (prostate volume reduction of ~20-25%, improvement in symptoms). Both reduce PSA by ~50% (must be accounted for in PSA interpretation). Both can cause erectile dysfunction, decreased libido, ejaculatory dysfunction."]','A','The 50% PSA reduction with 5-ARIs is clinically important: a PSA that is rising in a man on finasteride or dutasteride should be multiplied by 2 to estimate true PSA, and an unexplained rising PSA warrants prostate cancer investigation.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Prostate and Androgen Pharmacology','medium','flashcard','What is the testosterone flare with GnRH agonists in prostate cancer and how is it prevented?','["When a GnRH agonist (leuprorelin, goserelin, buserelin) is first administered, it causes initial receptor stimulation → surge in LH → testosterone spike (''flare'') lasting 1-2 weeks before receptor downregulation occurs. In men with metastatic prostate cancer, this testosterone surge can stimulate tumour growth, precipitating: worsening bone pain, pathological fractures, ureteric obstruction, or spinal cord compression. Prevention: co-prescribe a non-steroidal anti-androgen (bicalutamide 50-150 mg/day or cyproterone) starting 3 days BEFORE first GnRH agonist injection, continuing for the first 3-4 weeks."]','A','Bicalutamide for flare cover blocks androgen receptors at target tissues, preventing the biological effects of the testosterone surge even though testosterone itself rises. This is standard practice for GnRH agonist initiation in metastatic disease.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Prostate and Androgen Pharmacology','medium','flashcard','What is the mechanism of bicalutamide in prostate cancer treatment?','["Bicalutamide is a non-steroidal competitive antagonist at androgen receptors (AR). It competes with testosterone and DHT (the active androgen at the prostate) for AR binding, preventing their binding and downstream transcriptional activation of androgen-responsive genes (including PSA). Unlike surgical or medical castration, bicalutamide does NOT reduce serum testosterone (LH/FSH may actually rise as negative feedback is reduced). It blocks androgen action at the receptor level. This mechanism means it preserves (partially) sexual function and bone density compared to castration. However, resistance develops via AR overexpression or gain-of-function mutations."]','A','Bicalutamide monotherapy can cause gynaecomastia (testosterone converted to oestrogen peripherally, oestrogen action unopposed by bicalutamide because it is AR-selective not ER-selective). This can be prevented with prophylactic radiotherapy to breast tissue.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Prostate and Androgen Pharmacology','hard','flashcard','What is abiraterone acetate and why is prednisolone prescribed alongside it?','["Abiraterone acetate is a prodrug hydrolysed to abiraterone, an irreversible inhibitor of CYP17A1 (17-alpha hydroxylase/C17,20-lyase). This enzyme catalyses two key steps in androgen synthesis from pregnenolone: 17-alpha hydroxylation and 17,20-lyase cleavage. Blocking CYP17A1 at ALL sites of androgen synthesis (testes, adrenal glands, intratumoural) reduces testosterone to undetectable levels even in castration-resistant disease. However, blocking CYP17A1 also impairs cortisol synthesis → ACTH rises → adrenal precursors accumulate → mineralocorticoid excess (hypertension, hypokalaemia, fluid retention). Prednisolone (5 mg BD) suppresses ACTH and replaces cortisol, preventing mineralocorticoid toxicity."]','A','Abiraterone + prednisolone (or prednisone) is a standard regimen in metastatic CRPC. The combination with enzalutamide is also used. Monitoring: BP, K+, LFTs (hepatotoxicity can occur). Approved for both pre- and post-chemotherapy CRPC.','universal',true,'{year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Prostate and Androgen Pharmacology','hard','flashcard','How does enzalutamide overcome bicalutamide resistance in castration-resistant prostate cancer?','["Bicalutamide resistance mechanisms: AR overexpression (amplification), AR gain-of-function mutations (AR becomes activated by bicalutamide itself — agonist switch), AR splice variants (AR-V7, lacks ligand-binding domain — constitutively active). Enzalutamide (Xtandi) overcomes resistance by: (1) Higher AR binding affinity (5-8x greater than bicalutamide). (2) Inhibits AR nuclear translocation (prevents AR-DNA interaction even if AR is occupied). (3) Inhibits AR-coactivator recruitment. (4) No agonist switch at overexpressed AR. It cannot overcome AR-V7-driven resistance (which lacks the ligand-binding domain entirely)."]','A','Enzalutamide is second-generation anti-androgen for CRPC. Key side effects: fatigue, hypertension, seizure risk (cross BBB — avoid in epilepsy), falls. AR-V7 expression in circulating tumour cells predicts resistance to both enzalutamide and abiraterone.','universal',true,'{year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Prostate and Androgen Pharmacology','medium','flashcard','What is degarelix and what advantages does it have over leuprorelin for prostate cancer?','["Degarelix (Firmagon) is a GnRH receptor antagonist given by SC injection monthly. It immediately and competitively blocks GnRH receptors → rapid FSH and LH suppression → testosterone reduced to castration levels within 3 days. Advantages over GnRH agonists (leuprorelin, goserelin): (1) No testosterone flare — no need for anti-androgen cover. (2) Faster testosterone suppression (3 days vs. 2-4 weeks). (3) May have immunological anti-tumour effects (reduced FSH receptor signalling on prostate cancer cells). Disadvantages: injection site reactions (pain, erythema, nodule) — more frequent than GnRH agonists; no long-acting formulation."]','A','Degarelix is preferred when rapid testosterone suppression is needed (acute spinal cord compression, severe bone pain) where waiting for GnRH agonist downregulation is not acceptable. It avoids the need for anti-androgen flare prophylaxis.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Prostate and Androgen Pharmacology','easy','flashcard','What are the sexual side effects of 5-alpha reductase inhibitors (finasteride/dutasteride)?','["Sexual side effects occur in approximately 5-8% of men: (1) Decreased libido. (2) Erectile dysfunction (ED). (3) Ejaculatory dysfunction (reduced ejaculate volume). These effects are thought to result from reduced DHT, which plays a role in normal sexual function. Most effects are reversible on stopping the drug. However, ''post-finasteride syndrome'' describes persistent sexual dysfunction and depressive symptoms persisting after drug discontinuation — the mechanism is debated (possible neuroactive steroid effect on 5-alpha reductase in CNS). Gynecomastia/breast tenderness also occurs (~1%) due to altered androgen/oestrogen ratio."]','A','Sexual side effects should be disclosed when prescribing 5-ARIs, particularly to younger men taking finasteride 1 mg for alopecia. Post-finasteride syndrome is recognised by regulatory bodies but remains controversial in terms of prevalence and mechanism.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Prostate and Androgen Pharmacology','hard','flashcard','What are the long-term effects of androgen deprivation therapy (ADT) on metabolic health and bone density?','["ADT (GnRH agonists/antagonists, bilateral orchidectomy) causes testosterone suppression. Long-term metabolic effects: (1) Osteoporosis: testosterone maintains bone density; ADT causes accelerated bone loss (3-5% per year) → increased fracture risk. DEXA monitoring and bisphosphonates/denosumab are used. (2) Metabolic syndrome: insulin resistance, weight gain (especially visceral fat), dyslipidaemia, hyperglycaemia → increased cardiovascular risk. (3) Sarcopenia: reduced muscle mass and strength. (4) Anaemia (androgen-stimulated erythropoiesis suppressed). (5) Cognitive effects: possible increased dementia risk. (6) Hot flushes, gynaecomastia, sexual dysfunction."]','A','Long-term ADT complications significantly impact quality of life in prostate cancer survivors. Bone health monitoring (DEXA every 1-2 years), cardiovascular risk management, and exercise programmes are important components of holistic care during ADT.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Prostate and Androgen Pharmacology','medium','flashcard','What is cyproterone acetate and how does it compare to bicalutamide?','["Cyproterone acetate (CPA) is a STEROIDAL anti-androgen. It is a progestogenic androgen receptor antagonist that also suppresses LH secretion (reducing testosterone synthesis centrally). Unlike bicalutamide (non-steroidal, no central effect): CPA reduces both androgen receptor activation AND testosterone levels. Side effects: hepatotoxicity (more common than bicalutamide; LFT monitoring essential), cardiovascular events (progestogenic thrombogenic effect), depression, fatigue, gynaecomastia. Uses: prostate cancer, BPH (limited), treatment of hypersexuality, hirsutism/virilisation in women (as Diane-35 with ethinylestradiol for acne/PCOS)."]','A','CPA''s dual mechanism (AR blockade + central LH suppression) means testosterone levels fall with CPA monotherapy, unlike bicalutamide where testosterone may rise. Hepatotoxicity risk means regular LFT monitoring is mandatory.','universal',false,'{year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Oxytocics and Uterotonics','medium','flashcard','What is dinoprostone (PGE2) and when is it used in obstetrics?','["Dinoprostone is synthetic prostaglandin E2, available as vaginal gel (Prostin E2) or controlled-release pessary (Propess). Uses: (1) Cervical ripening prior to induction of labour — softens and dilates the cervix (''ripening''). (2) Induction of labour in women with unfavourable cervix (Bishop score <6). Mechanism: PGE2 receptors in the cervix mediate collagenase activation and cervical softening; also stimulates myometrial contractions. Main risk: uterine hyperstimulation (managed by removing the pessary and giving terbutaline SC). Requires continuous CTG monitoring."]','A','Dinoprostone is the standard pharmacological agent for cervical ripening in the UK. The controlled-release pessary (Propess) remains in situ for up to 24 hours and can be removed if hyperstimulation occurs. Misoprostol (cheaper, more stable) is used in low-resource settings.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Tocolytics','hard','flashcard','What is the clinical approach to tocolysis in a woman with a twin pregnancy in preterm labour at 27 weeks?','["Approach: (1) Confirm diagnosis (cervical length, fFN test if uncertain). (2) Administer corticosteroids (betamethasone 12 mg IM x2 doses 24 hours apart) — most critical step. (3) Administer MgSO4 for neuroprotection (loading 4g IV then 1g/hour). (4) Consider tocolytic for 48-hour window: nifedipine (oral) or atosiban (IV). (5) Consider in utero transfer to tertiary NICU. Twin pregnancies have higher risk of OHSS from beta-agonists; atosiban or nifedipine preferred. Multiple pregnancy is not a contraindication to tocolysis but raises OHSS risk with beta-agonists specifically."]','A','Twin pregnancies are at high risk of preterm labour. The management priorities are: steroid cover, neuroprotection, and safe transfer — tocolysis facilitates these. OHSS risk from beta-agonists is particularly elevated in multiple pregnancy so atosiban is safer.','universal',false,'{year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Drugs in Pregnancy','hard','flashcard','What is the approach to managing epilepsy in a woman who becomes pregnant?','["Pre-pregnancy: switch to the lowest-teratogenic-risk antiepileptic if possible (lamotrigine or levetiracetam preferred; avoid valproate in women of childbearing potential). Prescribe 5 mg folic acid from preconception. During pregnancy: do NOT abruptly stop antiepileptics (seizure risk to mother and fetus is greater than drug teratogenicity risk). Monitor drug levels (pregnancy alters pharmacokinetics — increased clearance of lamotrigine due to increased glucuronidation). Adjust doses to maintain seizure control. Valproate: if already on valproate, involve neurology urgently; consider switching before conception. Advise VPPP compliance."]','A','The fundamental principle: uncontrolled seizures in pregnancy are more dangerous than the teratogenic risk of most antiepileptics. Abrupt discontinuation of antiepileptics can cause status epilepticus, which carries significant maternal and fetal mortality.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Pre-eclampsia Management','medium','flashcard','What antihypertensives can be used for chronic hypertension in pregnancy and which should be avoided?','["Safe to use: Labetalol (first-line in UK for acute and chronic), nifedipine MR (second-line), methyldopa (long-established safety record — third-line due to sedation/depression). Avoid: ACE inhibitors (renal dysgenesis, oligohydramnios — contraindicated in 2nd/3rd trimester). ARBs (same mechanism as ACEi — contraindicated). Atenolol (associated with fetal growth restriction). Diuretics (reduce circulating volume — harmful in pre-eclampsia where intravascular volume is already reduced). Avoid spironolactone (anti-androgen effects — potential fetal feminisation of male fetus)."]','A','Managing chronic hypertension in pregnancy requires switching away from ACEi/ARBs before or as soon as pregnancy is confirmed. Target BP: 135/85 mmHg (NICE 2019 — lower targets risk placental insufficiency).','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Pre-eclampsia Management','medium','flashcard','What is HELLP syndrome and how does pharmacological management differ from standard pre-eclampsia?','["HELLP = Haemolysis, Elevated Liver enzymes, Low Platelets — a severe variant of pre-eclampsia. Features: microangiopathic haemolytic anaemia, LDH >600, AST/ALT >2x upper limit, platelets <100 x10^9/L. Management differences: (1) Platelet transfusion if <20 x10^9/L or before caesarean section if <50 x10^9/L. (2) Avoid regional anaesthesia if platelets <80 x10^9/L. (3) Corticosteroids (dexamethasone) — controversial, may improve platelet count transiently. (4) Definitive: DELIVERY regardless of gestation. (5) Standard antihypertensives and MgSO4 as for severe pre-eclampsia. Plasma exchange if diagnosis unclear (TTP differential)."]','A','HELLP syndrome carries significant maternal mortality risk (1-3%). The low platelet count creates anaesthetic and surgical challenges. Delivery is the only curative treatment. The diagnosis must be distinguished from TTP, HUS, and acute fatty liver of pregnancy.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Fertility Drugs','hard','flashcard','What is the role of progesterone supplementation in IVF and why is it needed?','["In IVF cycles, oocyte retrieval removes the granulosa cells that would normally form the corpus luteum. Additionally, GnRH agonist/antagonist use suppresses LH, further impairing corpus luteum function. Without a corpus luteum, progesterone secretion is inadequate to prepare the endometrium for implantation. Luteal phase support: progesterone pessaries (micronised progesterone 400-800 mg/day vaginally), progesterone injections, or oral dydrogesterone are given from egg collection until 12 weeks gestation (when the placenta takes over progesterone production). Without luteal support, IVF success rates fall dramatically."]','A','Vaginal progesterone (Utrogestan, Cyclogest) is the standard route for luteal support in IVF because vaginal administration achieves high uterine concentrations (''first uterine pass effect'') with lower systemic levels than oral, minimising systemic side effects.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','HRT','medium','flashcard','What is the ''timing hypothesis'' (window of opportunity) for cardiovascular effects of HRT?','["The timing hypothesis: HRT started close to menopause onset (within 10 years of last period, or age <60) may protect against cardiovascular disease by preserving endothelial function and reducing atherosclerotic plaque progression. HRT started in older women (>60 or >10 years post-menopause) — when established atherosclerosis is present — may be harmful (plaque destabilisation). The WHI trial enrolled older women (mean age 63) and found increased cardiac events, leading to overestimation of cardiovascular risk of HRT. Observational data and WHI subgroup analyses support the timing hypothesis."]','A','The timing hypothesis is important in counselling women about HRT and cardiovascular risk. Young menopausal women (<60, starting HRT early) are likely to benefit cardiovascularly; the WHI data are not applicable to this group.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','HRT','medium','flashcard','What is the difference between sequential and continuous combined HRT regimens?','["Sequential (cyclical) combined HRT: oestrogen taken continuously + progestogen added for 10-14 days per month. Results in regular withdrawal bleed at the end of each progestogen phase. Used in perimenopausal women (within 1 year of last period) or those preferring regular bleeds. Continuous combined HRT: oestrogen + progestogen taken together every day without a break. No planned withdrawal bleed (may have irregular spotting for first 3-6 months, then amenorrhoea). Used in postmenopausal women (>1 year post-menopause). Advantage: no monthly bleed. If a postmenopausal woman on continuous HRT develops unexpected bleeding, endometrial pathology must be excluded."]','A','Choosing between sequential and continuous depends on time since menopause and patient preference. Starting continuous combined HRT too early (in perimenopause) causes erratic bleeding as the endometrium is not yet consistently quiescent.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Drugs for Gynaecological Conditions','medium','flashcard','What NSAIDs are used in dysmenorrhoea and what is their mechanism?','["Dysmenorrhoea (painful periods) is mediated by prostaglandins (PGE2, PGF2-alpha) produced by the endometrium during menstruation. These cause myometrial spasm and vasoconstriction → ischaemic pain. NSAIDs (e.g., mefenamic acid, ibuprofen, naproxen) inhibit COX-1 and COX-2, reducing prostaglandin synthesis. This reduces both uterine cramping and blood loss (prostaglandins also promote fibrinolysis). Started at onset of menstruation or 1-2 days before (if cycle is predictable). Mefenamic acid 500 mg TDS is particularly effective as it also blocks prostaglandin receptors. NSAIDs reduce dysmenorrhoea in ~80% of women."]','A','NSAIDs are first-line for primary dysmenorrhoea (no identifiable pathology). Secondary dysmenorrhoea (endometriosis, fibroids, adenomyosis) requires treatment of the underlying cause. The COCP, LNG-IUS, and progestogens are hormonal alternatives.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
